  const toggleBtn = (onClick: () => void, active: boolean) => (
    <button onClick={onClick} className={`px-2.5 py-1 rounded-md font-bold text-[11px] border ${active ? 'bg-rose-50 text-rose-700 border-rose-200 hover:bg-rose-100' : 'bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100'}`}>
      {active ? 'Khóa' : 'Kích hoạt'}
    </button>
  );

  return (
    <div className="space-y-5">
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <Database className="w-5 h-5 text-blue-600" />
            <span>Danh mục dùng chung (Master Data)</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Catalog dùng chung cho Manifest/HBL/Truck Visit. Không hard-delete — chỉ khóa (active=false) để giữ lịch sử.
          </p>
        </div>
        <button
          onClick={() => setShowForm(true)}
          className="px-3.5 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-lg transition shadow-xs flex items-center space-x-1.5"
        >
          <Plus className="w-4 h-4" />
          <span>Thêm mới</span>
        </button>
      </div>

      <div className="flex gap-1 bg-white p-1.5 rounded-xl border border-slate-200 w-fit">
        {tabs.map((t) => {
