          <div className="bg-white rounded-xl max-w-sm w-full p-6 shadow-xl border border-slate-200 text-xs">
            <h3 id="master-data-dialog-1-title" className="text-base font-bold text-slate-900 mb-4">Thêm {tabs.find((t) => t.id === tab)?.label}</h3>
            <div className="space-y-3">
              <div>
                <label htmlFor="master-data-form-name" className="block font-semibold text-slate-700 mb-1">Tên*</label>
                <input id="master-data-form-name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg" />
