            >
              <div className="flex items-center justify-between">
                <div>
                  <div className="text-sm font-bold text-slate-900">{client.partnerName}</div>
                  <span className="font-mono text-indigo-700 font-semibold">{client.partnerCode}</span>
                </div>
                <span
