          <div className="space-y-3 text-xs">
            {dwellBuckets.map(bucket => <div key={bucket.label} className="p-3 bg-slate-50 text-slate-800 rounded-lg flex flex-wrap gap-2 items-center justify-between font-semibold"><span>{bucket.label}</span><span>{bucket.count} container · {bucket.percent}%</span></div>)}
